'use strict';
let common = {};

common.handleRpcErr = rpcErr => {
    let errMsg = '';

    try {
	errMsg = rpcErr.message || rpcErr.response.error;

	if (typeof errMsg === 'object') {
	    errMsg = errMsg.message || JSON.stringify(errMsg);
	}
    } catch (err) {
	errMsg = rpcErr;
    }

    return errMsg;
}

module.exports = common;
